import Mathlib

theorem putnam_2018_a1
  (a b : ℤ)
  (h : 0 < a ∧ 0 < b) :
  ((1 : ℚ) / a + (1 : ℚ) / b = (3 : ℚ) / 2018) ↔
    (⟨a, b⟩ ∈ ({(673, 1358114), (674, 340033), (1009, 2018),
      (2018, 1009), (340033, 674), (1358114, 673)} : Set (ℤ × ℤ))) := by
  constructor
  · -- Forward direction: if the equation holds, then (a,b) is in the solution set
    intro h_eq
    have h_pos : 0 < a := h.1
    have h_pos' : 0 < b := h.2
    -- Transform the equation to (3a - 2018)(3b - 2018) = 2018²
    have h_main : (3 * a - 2018) * (3 * b - 2018) = 2018 ^ 2 := by
      field_simp [h_pos.ne', h_pos'.ne'] at h_eq
      ring_nf at h_eq ⊢
      norm_cast at h_eq ⊢
      linarith
    -- Show that 3a - 2018 is a positive divisor of 2018²
    have h_div : (3 * a - 2018) ∣ 2018 ^ 2 := by
      use 3 * b - 2018
      rw [h_main]
    have h_pos_factor : 0 < 3 * a - 2018 := by
      by_contra h_neg
      have h_le : 3 * a - 2018 ≤ 0 := by linarith
      have h_a_le : a ≤ 672 := by
        omega
      have h_b_pos : 0 < b := h.2
      have h_b_ge : b ≥ 1 := by linarith
      have h_lhs : (1 : ℚ) / a + (1 : ℚ) / b > (3 : ℚ) / 2018 := by
        have h_a_pos : 0 < (a : ℚ) := by exact_mod_cast h_pos
        have h_b_pos' : 0 < (b : ℚ) := by exact_mod_cast h_b_pos
        have h_a_le_q : (a : ℚ) ≤ 672 := by exact_mod_cast h_a_le
        have h_inv_a : (1 : ℚ) / a ≥ (1 : ℚ) / 672 := by
          apply one_div_le_one_div_of_le
          · positivity
          · exact_mod_cast h_a_le
        have h_inv_b : (1 : ℚ) / b > 0 := by positivity
        calc
          (1 : ℚ) / a + (1 : ℚ) / b ≥ (1 : ℚ) / 672 + 0 := by linarith
          _ > (3 : ℚ) / 2018 := by norm_num
      linarith
    -- Since 3a - 2018 is a positive divisor of 2018² and ≡ 1 (mod 3)
    -- it must be one of the six specific values
    have h_cases : a = 673 ∨ a = 674 ∨ a = 1009 ∨ a = 2018 ∨ a = 340033 ∨ a = 1358114 := by
      have h_d : (3 * a - 2018) ∣ 2018 ^ 2 := h_div
      have h_d_pos : 0 < 3 * a - 2018 := h_pos_factor
      have h_d_mod : (3 * a - 2018) % 3 = 1 := by
