      have h_prime_1009 : Nat.Prime 1009 := by decide
      -- Enumerate all divisors of 2018² that are ≡ 1 (mod 3)
      have h_all_divs : ∀ (d : ℤ), d ∣ (2018 : ℤ) ^ 2 → 0 < d → d % 3 = 1 →
        d = 1 ∨ d = 4 ∨ d = 1009 ∨ d = 4036 ∨ d = 1018081 ∨ d = 4072324 := by
