        have : d ∣ 4072324 := by simpa [h_2018_sq] using hd_pos
        have : 0 < d := hd_pos
        have : d % 3 = 1 := hd_mod
        -- Since 2018² = 4 × 1009², divisors are of form 2^i × 1009^j
        -- Only those with i even satisfy d ≡ 1 (mod 3)
        have : d = 1 ∨ d = 4 ∨ d = 1009 ∨ d = 4036 ∨ d = 1018081 ∨ d = 4072324 := by
          -- Use interval_cases or explicit enumeration
          have h_bound : d ≤ 4072324 := by
            exact Int.le_of_dvd (by norm_num) hd_pos
          have h_lower : d ≥ 1 := by linarith
